import timefrom typing import Optionalfrom google import genaifrom google.genai import typesfrom config import (    GEMINI_API_KEY,    GEMINI_MODELS,    AI_TEMPERATURE,    AI_MAX_OUTPUT_TOKENS,    RETRY_DELAY_SECONDS,    MODEL_RETRY_COUNT,)# ============================================================# MafiyaAI AI Engine# ============================================================if not GEMINI_API_KEY:    raise RuntimeError(        "GEMINI_API_KEY is not configured."    )# ============================================================# Gemini Client# ============================================================client = genai.Client(    api_key=GEMINI_API_KEY)# ============================================================# Model List# ============================================================MODELS = [    model_name.strip()    for model_name in GEMINI_MODELS    if model_name    and str(model_name).strip()]# ============================================================# Generation Configuration# ============================================================## IMPORTANT:# No system prompt is defined here.## All AI instructions/prompts come from:# backend/answer_builder.py## ============================================================GENERATION_CONFIG = types.GenerateContentConfig(    temperature=AI_TEMPERATURE,    max_output_tokens=AI_MAX_OUTPUT_TOKENS,)# ============================================================# Generate AI Response# ============================================================def generate_ai_response(    message: str,    conversation_context: Optional[str] = None,) -> str:    if message is None:        raise ValueError(            "Message cannot be None."        )    message = str(message).strip()    if not message:        raise ValueError(            "Message cannot be empty."        )    # --------------------------------------------------------    # Build final request    # --------------------------------------------------------    #    # answer_builder.py already creates the complete prompt.    #    # Therefore conversation_context is treated as the    # complete prompt when provided.    #    # --------------------------------------------------------    if conversation_context:        prompt = str(            conversation_context        ).strip()    else:        prompt = message    if not prompt:        raise ValueError(            "Prompt cannot be empty."        )    last_error = None    # ========================================================    # Model Fallback Chain    # ========================================================    for model_name in MODELS:        # ----------------------------------------------------        # Retry current model        # ----------------------------------------------------        retry_count = max(            1,            MODEL_RETRY_COUNT        )        for attempt in range(            retry_count        ):            try:                response = client.models.generate_content(                    model=model_name,                    contents=prompt,                    config=GENERATION_CONFIG,                )                text = extract_response_text(                    response                )                if text:                    return text                last_error = RuntimeError(                    f"{model_name} returned an empty response."                )            except Exception as error:                last_error = error            # ------------------------------------------------            # Retry delay            # ------------------------------------------------            if attempt < retry_count - 1:                if RETRY_DELAY_SECONDS > 0:                    time.sleep(                        RETRY_DELAY_SECONDS                    )        # ----------------------------------------------------        # Current model failed.        #        # Immediately try the next model.        # ----------------------------------------------------        continue    # ========================================================    # All Models Failed    # ========================================================    if last_error:        raise RuntimeError(            "All MafiyaAI Gemini models failed. "            f"Last error: {last_error}"        ) from last_error    raise RuntimeError(        "MafiyaAI could not generate a response."    )# ============================================================# Extract Response Text# ============================================================def extract_response_text(    response) -> str:    if response is None:        return ""    # --------------------------------------------------------    # Standard Gemini response    # --------------------------------------------------------    try:        text = getattr(            response,            "text",            None        )        if text:            return str(                text            ).strip()    except Exception:        pass    # --------------------------------------------------------    # Candidate fallback    # --------------------------------------------------------    try:        candidates = getattr(            response,            "candidates",            None        )        if not candidates:            return ""        parts = []        for candidate in candidates:            content = getattr(                candidate,                "content",                None            )            if not content:                continue            candidate_parts = getattr(                content,                "parts",                None            ) or []            for part in candidate_parts:                part_text = getattr(                    part,                    "text",                    None                )                if part_text:                    parts.append(                        str(part_text)                    )        if parts:            return "\n".join(                parts            ).strip()    except Exception:        pass    return ""# ============================================================# AI Connection Test# ============================================================def check_ai_connection() -> bool:    try:        response = generate_ai_response(            "Reply with exactly: OK"        )        return (            response.strip().upper()            == "OK"        )    except Exception as error:        # Keep the original error available to callers        # that directly call generate_ai_response().        #        # The health endpoint can handle the failure.        return False# ============================================================# Get Active Models# ============================================================def get_available_models():    return list(        MODELS    )# ============================================================# AI Engine Status# ============================================================def get_ai_status():    return {        "configured": bool(            GEMINI_API_KEY        ),        "models": get_available_models(),        "model_count": len(            MODELS        ),        "retry_delay_seconds":            RETRY_DELAY_SECONDS,        "retry_count":            MODEL_RETRY_COUNT,        "message_limit":            None,        "memory_limit":            None,    }# ============================================================# Public Exports# ============================================================__all__ = [    "generate_ai_response",    "extract_response_text",    "check_ai_connection",    "get_available_models",    "get_ai_status",]